<?php
function diarioReportQuery($p,$db){
 $from=diarioDate(($p['desde']??substr(diarioNow(),0,7).'-01').' 00:00:00');$to=diarioDate(($p['hasta']??substr(diarioNow(),0,10)).' 23:59:59');if($to<$from)throw new InvalidArgumentException('Revisa el rango de fechas.');
 $sql="SELECT t.*,(SELECT COUNT(*) FROM Rhu_DiarioAdjunto a WHERE a.Tarea=t.Id) CantidadAdjuntos,COALESCE(e.Empleado,u.NombreUsuario,t.Usuario) ResponsableNombre,e.IdEmpleado EmpleadoKey,IFNULL(p.Cargo,'') Cargo FROM Rhu_DiarioTarea t LEFT JOIN Seg_Usuario u ON u.Usuario=t.Usuario LEFT JOIN Rhu_DiarioVinculo v ON v.Usuario=t.Usuario LEFT JOIN Rhu_Empleado e ON e.IdEmpleado=COALESCE(t.IdEmpleado,v.IdEmpleado) LEFT JOIN Rhu_PlanillaPersonal p ON p.IdEmpleado=e.IdEmpleado WHERE t.Inicio<=? AND t.Fin>=?";$params=[$to,$from];
 if(!empty($p['responsable'])){$person=(string)$p['responsable'];if(substr($person,0,2)==='e:'){$sql.=' AND e.IdEmpleado=?';$params[]=(int)substr($person,2);}elseif(substr($person,0,2)==='u:'){$value=substr($person,2);$s=$db->prepare('SELECT IdEmpleado FROM Rhu_DiarioVinculo WHERE Usuario=?');$s->execute([$value]);$employee=(int)$s->fetchColumn();$sql.=' AND (t.Usuario=? OR t.IdEmpleado=?)';$params[]=$value;$params[]=$employee;}else throw new InvalidArgumentException('Responsable inválido.');}
 if(!empty($p['estado'])){if(!in_array($p['estado'],['pendiente','en_curso','pausada','concluida','cancelada'],true))throw new InvalidArgumentException('Estado inválido.');$sql.=' AND t.Estado=?';$params[]=$p['estado'];}
 if(!empty($p['tipo'])){if(!in_array($p['tipo'],['general','programacion','soporte','mantenimiento','reunion'],true))throw new InvalidArgumentException('Tipo de trabajo inválido.');$sql.=' AND t.TipoTrabajo=?';$params[]=$p['tipo'];}
 if(!empty($p['buscar'])){$search=diarioText($p['buscar'],180);$sql.=' AND (t.Proyecto LIKE ? OR t.Ticket LIKE ? OR t.Titulo LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}
 if(($p['calidad']??'')!==''){if($p['calidad']==='sin')$sql.=' AND t.Estado=\'concluida\' AND t.Calidad IS NULL';elseif(in_array((string)$p['calidad'],['1','2','3','4','5'],true)){$sql.=' AND t.Calidad=?';$params[]=(int)$p['calidad'];}else throw new InvalidArgumentException('Calificación inválida.');}
 return [$sql,$params];
}
function diarioReportStats($rows,$now){
 $s=['total'=>0,'concluidas'=>0,'validadas'=>0,'aTiempo'=>0,'vencidas'=>0,'segundos'=>0,'posibles'=>0,'logrados'=>0,'calidadSuma'=>0,'activas'=>0,'programacion'=>0,'programacionConcluida'=>0,'soporte'=>0,'soporteResuelto'=>0,'estimadoMin'=>0];$groups=[];$states=[];$grades=array_fill(1,5,0);
 foreach($rows as $t){$key=!empty($t['EmpleadoKey'])?'e:'.$t['EmpleadoKey']:(!empty($t['IdEmpleado'])?'e:'.$t['IdEmpleado']:'u:'.$t['Usuario']);if(!isset($groups[$key]))$groups[$key]=array_merge($s,['key'=>$key,'nombre'=>$t['ResponsableNombre'],'cargo'=>$t['Cargo']]);$g=&$groups[$key];$states[$t['Estado']]=($states[$t['Estado']]??0)+1;
  $sec=(int)$t['Segundos'];if($t['EnCursoDesde'])$sec+=max(0,strtotime($now.' America/Lima')-strtotime($t['EnCursoDesde'].' America/Lima'));
  foreach([&$s,&$g] as &$x){$x['total']++;$x['segundos']+=$sec;if(($t['TipoTrabajo']??'')==='programacion'){$x['programacion']++;if($t['Estado']==='concluida')$x['programacionConcluida']++;}if(($t['TipoTrabajo']??'')==='soporte'){$x['soporte']++;if($t['Estado']==='concluida')$x['soporteResuelto']++;}if($t['Estado']==='cancelada')continue;$x['activas']++;$x['estimadoMin']+=(int)($t['EstimadoMin']??0);$weight=(int)$t['Puntos'];$x['posibles']+=$weight;if($t['Estado']==='concluida'){$x['concluidas']++;if($t['FinReal']&&$t['FinReal']<=$t['Fin'])$x['aTiempo']++;if($t['Calidad']!==null){$x['validadas']++;$x['calidadSuma']+=(int)$t['Calidad'];$ratio=(float)$t['Objetivo']>0?min(1,(float)$t['Realizado']/(float)$t['Objetivo']):1;$x['logrados']+=$weight*$ratio*(int)$t['Calidad']/5;}}elseif($t['Fin']<$now)$x['vencidas']++;}unset($x);if($t['Calidad']!==null)$grades[(int)$t['Calidad']]++;unset($g);
 }
 $finish=function($x){$x['calidad']=$x['validadas']?round($x['calidadSuma']/$x['validadas'],2):null;$x['logro']=$x['posibles']?round(100*$x['logrados']/$x['posibles'],1):0;$x['cumplimiento']=$x['activas']?round(100*$x['concluidas']/$x['activas'],1):0;$x['puntualidad']=$x['concluidas']?round(100*$x['aTiempo']/$x['concluidas'],1):0;$x['logrados']=round($x['logrados'],2);return $x;};
 return ['resumen'=>$finish($s),'equipo'=>array_map($finish,array_values($groups)),'estados'=>$states,'calificaciones'=>$grades];
}
function diarioRegisterDashboard($app,$auth){
 $app->get('/diario/dashboard',function($q,$r){$i=$q->getAttribute('diario');if(empty($i['superadmin']))return $r->withJson(['error'=>'Dashboard general reservado a superadmin.'],403);$p=$q->getQueryParams();[$sql,$params]=diarioReportQuery($p,$this->db);$s=$this->db->prepare($sql.' ORDER BY t.Inicio DESC,t.Id DESC');$s->execute($params);$page=max(1,(int)($p['pagina']??1));$offset=($page-1)*100;$rows=[];$count=0;
  $iterator=(function()use($s,&$rows,&$count,$offset){while($row=$s->fetch(PDO::FETCH_ASSOC)){if($count>=$offset&&$count<$offset+100)$rows[]=$row;$count++;yield $row;}})();$data=diarioReportStats($iterator,diarioNow());$data['actividades']=$rows;$data['pagina']=$page;$data['paginas']=max(1,(int)ceil($count/100));$data['ahora']=diarioNow();return $r->withJson($data);
 })->add($auth);
 $app->get('/diario/reporte.csv',function($q,$r){$i=$q->getAttribute('diario');if(empty($i['superadmin']))return $r->withJson(['error'=>'Reporte general reservado a superadmin.'],403);[$sql,$params]=diarioReportQuery($q->getQueryParams(),$this->db);$s=$this->db->prepare($sql.' ORDER BY t.Inicio,t.Id');$s->execute($params);$f=fopen('php://temp','w+');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['ID','Responsable','Cargo','Tipo de trabajo','Cliente / proyecto','Ticket / referencia','Estimado (min)','Tiempo trabajado (seg)','Imagenes adjuntas','Indicaciones','Inicio real','Actividad','Inicio previsto (Lima)','Fin previsto (Lima)','Estado','Meta','Unidad','Logrado','Calidad / 5','Peso','Resultado','Evidencia','Conclusión','Evaluador','Reconocimiento'],';');
  while($t=$s->fetch(PDO::FETCH_ASSOC)){if($t['EnCursoDesde'])$t['Segundos']+=max(0,strtotime(diarioNow().' America/Lima')-strtotime($t['EnCursoDesde'].' America/Lima'));$cells=[];foreach(['Id','ResponsableNombre','Cargo','TipoTrabajo','Proyecto','Ticket','EstimadoMin','Segundos','CantidadAdjuntos','Indicaciones','InicioReal','Titulo','Inicio','Fin','Estado','Objetivo','Unidad','Realizado','Calidad','Puntos','Resultado','Evidencia','FinReal','Evaluador','Reconocimiento'] as $key){$v=(string)($t[$key]??'');if(preg_match('/^[\s]*[=+@\-]/u',$v))$v="'".$v;$cells[]=$v;}fputcsv($f,$cells,';');}rewind($f);$r->getBody()->write(stream_get_contents($f));fclose($f);return $r->withHeader('Content-Type','text/csv; charset=utf-8')->withHeader('Content-Disposition','attachment; filename="actividades-general.csv"');
 })->add($auth);
}
